CREATE TABLE `report_exports` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`report_type` ENUM('opportunity','trend','team') NOT NULL,`format` ENUM('csv') NOT NULL,`status` ENUM('queued','leased','retry_scheduled','succeeded','dead_letter','expired') NOT NULL DEFAULT 'queued',`attempt_count` INT UNSIGNED NOT NULL DEFAULT 0,`available_at` DATETIME(3) NOT NULL,`leased_by` VARCHAR(120) CHARACTER SET ascii NULL,`lease_expires_at` DATETIME(3) NULL,`filename` VARCHAR(220) NOT NULL,`row_count` INT UNSIGNED NULL,`byte_size` BIGINT UNSIGNED NULL,`expires_at` DATETIME(3) NOT NULL,`last_error_code` VARCHAR(80) CHARACTER SET ascii NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_report_exports_claim`(`status`,`available_at`,`lease_expires_at`),KEY `idx_report_exports_scope`(`organization_id`,`workspace_id`,`created_at`),KEY `idx_report_exports_expiry`(`status`,`expires_at`),CONSTRAINT `fk_report_export_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_report_export_workspace` FOREIGN KEY(`workspace_id`) REFERENCES `workspaces`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_report_export_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `report_export_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route_key` VARCHAR(160) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(128) CHARACTER SET ascii NOT NULL,`export_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_report_export_operations`(`actor_id`,`route_key`,`idempotency_key`),CONSTRAINT `fk_report_export_operation_export` FOREIGN KEY(`export_id`) REFERENCES `report_exports`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
